{
  "name": "@codemcp/workflows-opencode",
  "version": "6.24.2",
  "description": "OpenCode plugin for structured development workflows",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "files": [
    "dist/**/*",
    "resources/**/*"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "scripts": {
    "build": "tsup && pnpm copy-resources",
    "copy-resources": "rm -rf resources && cp -r ../core/resources .",
    "dev": "tsc --watch",
    "clean:build": "rimraf ./dist",
    "test": "vitest --run",
    "lint": "oxlint .",
    "lint:fix": "oxlint --fix .",
    "format:check": "prettier --check .",
    "format": "prettier --write ."
  },
  "dependencies": {
    "effect": "4.0.0-beta.48"
  },
  "devDependencies": {
    "@codemcp/workflows-core": "workspace:*",
    "@codemcp/workflows-server": "workspace:*",
    "@opencode-ai/plugin": "*",
    "rimraf": "^6.0.1",
    "tsup": "^8.0.0",
    "vitest": "4.0.18"
  },
  "peerDependencies": {
    "@anthropic-ai/sdk": "*",
    "@opencode-ai/plugin": "*",
    "zod": ">=4.1.8"
  },
  "peerDependenciesMeta": {
    "@anthropic-ai/sdk": {
      "optional": true
    },
    "@opencode-ai/plugin": {
      "optional": false
    },
    "zod": {
      "optional": false
    }
  },
  "keywords": [
    "opencode",
    "plugin",
    "workflows",
    "development"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/codemcp/workflows.git",
    "directory": "packages/opencode-plugin"
  }
}
